CREATE TABLE IF NOT EXISTS "players" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account identity from the platform layer. Kept opaque so the economy service never has to call the account service to answer a balance question.
	"external_id" VARCHAR(120) NOT NULL UNIQUE,
	-- Name shown on receipts and in support tooling.
	"display_name" VARCHAR(40) NOT NULL,
	-- ISO 3166-1 alpha-2, from the store account. Drives regional pricing and tax treatment; null until a first purchase reveals it.
	"country_code" CHAR(2),
	-- Audience bucket used to pick a price from offer_prices, e.g. new_player or returning. A stored column rather than a live computation so a price cannot change under a player mid-session.
	"segment_code" VARCHAR(40) NOT NULL DEFAULT 'default',
	-- Set after repeated chargebacks. Blocks new purchases without freezing the wallet, so the player keeps what they legitimately earned.
	"is_payment_blocked" BOOLEAN NOT NULL DEFAULT false,
	-- First seen by the economy service.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "players" IS 'A spending account holder. Everything monetary hangs off this row, and nothing about gameplay progression lives here.';
COMMENT ON COLUMN "players"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "players"."external_id" IS 'Account identity from the platform layer. Kept opaque so the economy service never has to call the account service to answer a balance question.';
COMMENT ON COLUMN "players"."display_name" IS 'Name shown on receipts and in support tooling.';
COMMENT ON COLUMN "players"."country_code" IS 'ISO 3166-1 alpha-2, from the store account. Drives regional pricing and tax treatment; null until a first purchase reveals it.';
COMMENT ON COLUMN "players"."segment_code" IS 'Audience bucket used to pick a price from offer_prices, e.g. new_player or returning. A stored column rather than a live computation so a price cannot change under a player mid-session.';
COMMENT ON COLUMN "players"."is_payment_blocked" IS 'Set after repeated chargebacks. Blocks new purchases without freezing the wallet, so the player keeps what they legitimately earned.';
COMMENT ON COLUMN "players"."created_at" IS 'First seen by the economy service.';

CREATE TABLE IF NOT EXISTS "currencies" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Stable key, e.g. gems or coins. Used everywhere in configuration; the numeric id never appears in game data.
	"code" VARCHAR(24) NOT NULL UNIQUE,
	-- Display name.
	"name" VARCHAR(60) NOT NULL,
	-- hard | soft | event. Hard currency is bought with real money and must reconcile against store revenue; soft is earned and is free to inflate.
	"kind" VARCHAR(16) NOT NULL,
	-- Whether real money can mint it. True only for hard currency, and it is the flag that decides whether a balance carries a refund liability.
	"is_purchasable" BOOLEAN NOT NULL DEFAULT false,
	-- Whether players may move it between accounts. False for almost everything, because a tradable currency is a money transmission problem.
	"is_tradable" BOOLEAN NOT NULL DEFAULT false,
	-- Lifetime for event currency, which is deliberately made worthless after a season. Null for currency that never expires.
	"expires_after_days" INTEGER,
	-- Cap on a single wallet, in the smallest unit. Null for uncapped. A cap is the cheapest defence against an overflow exploit becoming permanent.
	"max_balance_minor" BIGINT,
	-- Display order in the currency bar.
	"sort_order" SMALLINT NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "currencies" IS 'The kinds of value in the game. Separating hard from soft is not cosmetic: hard currency is a deferred revenue liability that has to reconcile with store payouts, and soft currency is a game balance lever.';
COMMENT ON COLUMN "currencies"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "currencies"."code" IS 'Stable key, e.g. gems or coins. Used everywhere in configuration; the numeric id never appears in game data.';
COMMENT ON COLUMN "currencies"."name" IS 'Display name.';
COMMENT ON COLUMN "currencies"."kind" IS 'hard | soft | event. Hard currency is bought with real money and must reconcile against store revenue; soft is earned and is free to inflate.';
COMMENT ON COLUMN "currencies"."is_purchasable" IS 'Whether real money can mint it. True only for hard currency, and it is the flag that decides whether a balance carries a refund liability.';
COMMENT ON COLUMN "currencies"."is_tradable" IS 'Whether players may move it between accounts. False for almost everything, because a tradable currency is a money transmission problem.';
COMMENT ON COLUMN "currencies"."expires_after_days" IS 'Lifetime for event currency, which is deliberately made worthless after a season. Null for currency that never expires.';
COMMENT ON COLUMN "currencies"."max_balance_minor" IS 'Cap on a single wallet, in the smallest unit. Null for uncapped. A cap is the cheapest defence against an overflow exploit becoming permanent.';
COMMENT ON COLUMN "currencies"."sort_order" IS 'Display order in the currency bar.';

CREATE TABLE IF NOT EXISTS "wallets" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owner. Null for system accounts - the mint, the sinks and escrow - which is what makes every transaction balance.
	"player_id" BIGINT,
	-- Currency held. A wallet holds exactly one currency, so a balance never needs a unit lookup.
	"currency_id" BIGINT NOT NULL,
	-- player | mint | sink | escrow | promo. The mint is where granted currency comes from and a sink is where spent currency goes, so nothing is ever created or destroyed mid-air.
	"account_kind" VARCHAR(24) NOT NULL DEFAULT 'player',
	-- Current balance in the smallest unit. A materialised sum of the ledger entries, never the source of truth.
	"balance_minor" BIGINT NOT NULL DEFAULT 0,
	-- Everything ever added. With its debit counterpart it gives sources-and-sinks reporting without scanning the ledger.
	"lifetime_credited_minor" BIGINT NOT NULL DEFAULT 0,
	-- Everything ever removed. balance_minor must equal credited minus debited, which is the cheapest possible integrity check.
	"lifetime_debited_minor" BIGINT NOT NULL DEFAULT 0,
	-- Optimistic lock. Every write bumps it, so two concurrent spends cannot both read the same balance and both succeed.
	"version" INTEGER NOT NULL DEFAULT 0,
	-- Last movement.
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "wallets" IS 'One balance per player per currency, plus the system accounts that make double entry possible. The balance is a cache of the ledger and can always be rebuilt from it; the ledger can never be rebuilt from the balance.';
COMMENT ON COLUMN "wallets"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "wallets"."player_id" IS 'Owner. Null for system accounts - the mint, the sinks and escrow - which is what makes every transaction balance.';
COMMENT ON COLUMN "wallets"."currency_id" IS 'Currency held. A wallet holds exactly one currency, so a balance never needs a unit lookup.';
COMMENT ON COLUMN "wallets"."account_kind" IS 'player | mint | sink | escrow | promo. The mint is where granted currency comes from and a sink is where spent currency goes, so nothing is ever created or destroyed mid-air.';
COMMENT ON COLUMN "wallets"."balance_minor" IS 'Current balance in the smallest unit. A materialised sum of the ledger entries, never the source of truth.';
COMMENT ON COLUMN "wallets"."lifetime_credited_minor" IS 'Everything ever added. With its debit counterpart it gives sources-and-sinks reporting without scanning the ledger.';
COMMENT ON COLUMN "wallets"."lifetime_debited_minor" IS 'Everything ever removed. balance_minor must equal credited minus debited, which is the cheapest possible integrity check.';
COMMENT ON COLUMN "wallets"."version" IS 'Optimistic lock. Every write bumps it, so two concurrent spends cannot both read the same balance and both succeed.';
COMMENT ON COLUMN "wallets"."updated_at" IS 'Last movement.';

CREATE UNIQUE INDEX "uq_wallets_currency_kind_player"
ON "wallets" ("currency_id", "account_kind", "player_id");
CREATE INDEX "idx_wallets_player"
ON "wallets" ("player_id");

CREATE TABLE IF NOT EXISTS "ledger_transactions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Currency moved. A transaction never mixes currencies; a currency exchange is two transactions linked by reference.
	"currency_id" BIGINT NOT NULL,
	-- grant | purchase | spend | transfer | refund | expiry | adjustment. The verb, used for economy dashboards.
	"kind" VARCHAR(24) NOT NULL,
	-- Why it happened, e.g. quest_reward, shop_purchase, battle_pass_claim. This is the source or sink label every economy report groups by.
	"reason_code" VARCHAR(60) NOT NULL,
	-- Caller-supplied key. Unique across the table, so a retried grant after a timeout is a no-op rather than free money.
	"idempotency_key" VARCHAR(120) NOT NULL UNIQUE,
	-- Transaction this one undoes. A refund is never an edit - it is a new transaction with the opposite entries pointing back at the original.
	"reverses_transaction_id" BIGINT,
	-- Who or what initiated it: a service name, a support operator, a scheduled job. Null for player-initiated actions, which are implied by the entries.
	"actor" VARCHAR(80),
	-- purchase | claim | quest | trade | support_ticket. Names the table reference_id points into.
	"reference_type" VARCHAR(24),
	-- Id within reference_type. Not a foreign key, because the ledger must outlive anything it describes.
	"reference_id" BIGINT,
	-- Context worth keeping for an investigation: offer code, campaign, client build. Schemaless so a new source needs no migration.
	"metadata" JSONB,
	-- Ledger time. The ledger is strictly append-only: rows are never updated or deleted after this is written.
	"occurred_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "ledger_transactions" IS 'The journal header. One transaction groups two or more entries that must sum to zero, which is what turns a pile of balance updates into an economy you can audit.';
COMMENT ON COLUMN "ledger_transactions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "ledger_transactions"."currency_id" IS 'Currency moved. A transaction never mixes currencies; a currency exchange is two transactions linked by reference.';
COMMENT ON COLUMN "ledger_transactions"."kind" IS 'grant | purchase | spend | transfer | refund | expiry | adjustment. The verb, used for economy dashboards.';
COMMENT ON COLUMN "ledger_transactions"."reason_code" IS 'Why it happened, e.g. quest_reward, shop_purchase, battle_pass_claim. This is the source or sink label every economy report groups by.';
COMMENT ON COLUMN "ledger_transactions"."idempotency_key" IS 'Caller-supplied key. Unique across the table, so a retried grant after a timeout is a no-op rather than free money.';
COMMENT ON COLUMN "ledger_transactions"."reverses_transaction_id" IS 'Transaction this one undoes. A refund is never an edit - it is a new transaction with the opposite entries pointing back at the original.';
COMMENT ON COLUMN "ledger_transactions"."actor" IS 'Who or what initiated it: a service name, a support operator, a scheduled job. Null for player-initiated actions, which are implied by the entries.';
COMMENT ON COLUMN "ledger_transactions"."reference_type" IS 'purchase | claim | quest | trade | support_ticket. Names the table reference_id points into.';
COMMENT ON COLUMN "ledger_transactions"."reference_id" IS 'Id within reference_type. Not a foreign key, because the ledger must outlive anything it describes.';
COMMENT ON COLUMN "ledger_transactions"."metadata" IS 'Context worth keeping for an investigation: offer code, campaign, client build. Schemaless so a new source needs no migration.';
COMMENT ON COLUMN "ledger_transactions"."occurred_at" IS 'Ledger time. The ledger is strictly append-only: rows are never updated or deleted after this is written.';

CREATE INDEX "idx_ledger_tx_currency_kind_time"
ON "ledger_transactions" ("currency_id", "kind", "occurred_at");
CREATE INDEX "idx_ledger_tx_reason_time"
ON "ledger_transactions" ("reason_code", "occurred_at");
CREATE INDEX "idx_ledger_tx_reverses"
ON "ledger_transactions" ("reverses_transaction_id");

CREATE TABLE IF NOT EXISTS "ledger_entries" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Journal entry this leg belongs to.
	"transaction_id" BIGINT NOT NULL,
	-- Account the leg moves. Player wallets on one side, a mint or sink wallet on the other.
	"wallet_id" BIGINT NOT NULL,
	-- Signed amount in the smallest unit. Positive credits the wallet, negative debits it, and the deltas of one transaction must sum to exactly zero.
	"delta_minor" BIGINT NOT NULL,
	-- Wallet balance immediately after this leg. Stored so a statement reads as a running balance without a window function over the whole history.
	"balance_after" BIGINT NOT NULL,
	-- Write time, equal to the transaction time for every leg it contains.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "ledger_entries" IS 'The legs of a transaction, and the only place currency is actually created or destroyed - which is to say, never. Granting a hundred gems debits the mint wallet by a hundred and credits the player by a hundred, so every coin in the game has a traceable origin.';
COMMENT ON COLUMN "ledger_entries"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "ledger_entries"."transaction_id" IS 'Journal entry this leg belongs to.';
COMMENT ON COLUMN "ledger_entries"."wallet_id" IS 'Account the leg moves. Player wallets on one side, a mint or sink wallet on the other.';
COMMENT ON COLUMN "ledger_entries"."delta_minor" IS 'Signed amount in the smallest unit. Positive credits the wallet, negative debits it, and the deltas of one transaction must sum to exactly zero.';
COMMENT ON COLUMN "ledger_entries"."balance_after" IS 'Wallet balance immediately after this leg. Stored so a statement reads as a running balance without a window function over the whole history.';
COMMENT ON COLUMN "ledger_entries"."created_at" IS 'Write time, equal to the transaction time for every leg it contains.';

CREATE UNIQUE INDEX "uq_entries_transaction_wallet"
ON "ledger_entries" ("transaction_id", "wallet_id");
CREATE INDEX "idx_entries_wallet_sequence"
ON "ledger_entries" ("wallet_id", "id");

CREATE TABLE IF NOT EXISTS "shop_offers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Stable key used in configuration and in analytics, e.g. starter_bundle_v3.
	"code" VARCHAR(60) NOT NULL UNIQUE,
	-- Display name in the store.
	"name" VARCHAR(120) NOT NULL,
	-- What is delivered, as a key into the item catalogue. Deliberately not a foreign key; the catalogue lives in another service and ships with the client.
	"item_ref" VARCHAR(80) NOT NULL,
	-- Units delivered per purchase.
	"item_quantity" INTEGER NOT NULL DEFAULT 1,
	-- Currency the offer is priced in. A real-money offer points at the hard currency it mints, not at a fiat currency.
	"currency_id" BIGINT NOT NULL,
	-- Fallback price in the smallest unit, used when no audience rule matches.
	"base_price_minor" BIGINT NOT NULL,
	-- When the offer becomes buyable. Time windows are columns rather than a deploy, so a rotation is a data change.
	"starts_at" TIMESTAMPTZ NOT NULL,
	-- When it stops. Null for a permanent store entry.
	"ends_at" TIMESTAMPTZ,
	-- Purchase cap per account, counted against completed purchases. Null for unlimited.
	"max_per_player" INTEGER,
	-- Global stock for a limited drop. Null for unlimited.
	"max_total" INTEGER,
	-- Kill switch independent of the time window, for pulling a broken offer immediately.
	"is_active" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "shop_offers" IS 'A thing for sale. It carries a base price but not the price a given player sees, because that depends on who is asking - which is what offer_prices is for.';
COMMENT ON COLUMN "shop_offers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "shop_offers"."code" IS 'Stable key used in configuration and in analytics, e.g. starter_bundle_v3.';
COMMENT ON COLUMN "shop_offers"."name" IS 'Display name in the store.';
COMMENT ON COLUMN "shop_offers"."item_ref" IS 'What is delivered, as a key into the item catalogue. Deliberately not a foreign key; the catalogue lives in another service and ships with the client.';
COMMENT ON COLUMN "shop_offers"."item_quantity" IS 'Units delivered per purchase.';
COMMENT ON COLUMN "shop_offers"."currency_id" IS 'Currency the offer is priced in. A real-money offer points at the hard currency it mints, not at a fiat currency.';
COMMENT ON COLUMN "shop_offers"."base_price_minor" IS 'Fallback price in the smallest unit, used when no audience rule matches.';
COMMENT ON COLUMN "shop_offers"."starts_at" IS 'When the offer becomes buyable. Time windows are columns rather than a deploy, so a rotation is a data change.';
COMMENT ON COLUMN "shop_offers"."ends_at" IS 'When it stops. Null for a permanent store entry.';
COMMENT ON COLUMN "shop_offers"."max_per_player" IS 'Purchase cap per account, counted against completed purchases. Null for unlimited.';
COMMENT ON COLUMN "shop_offers"."max_total" IS 'Global stock for a limited drop. Null for unlimited.';
COMMENT ON COLUMN "shop_offers"."is_active" IS 'Kill switch independent of the time window, for pulling a broken offer immediately.';

CREATE INDEX "idx_offers_window"
ON "shop_offers" ("is_active", "starts_at", "ends_at");

CREATE TABLE IF NOT EXISTS "offer_prices" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Offer being priced.
	"offer_id" BIGINT NOT NULL,
	-- Who this price is for, matched against players.segment_code, a country or an experiment arm. The literal value default is the catch-all.
	"audience_code" VARCHAR(40) NOT NULL,
	-- Price for this audience, in the smallest unit of the offer currency.
	"price_minor" BIGINT NOT NULL,
	-- Tie-break when a player matches several audiences. Highest priority wins, so pricing is deterministic rather than dependent on row order.
	"priority" SMALLINT NOT NULL DEFAULT 0,
	-- Optional window for a temporary discount on one audience. Null means it applies for the whole offer window.
	"starts_at" TIMESTAMPTZ,
	-- End of the optional window.
	"ends_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "offer_prices" IS 'Personalised pricing as rows. Keeping prices out of the offer means a regional discount, a returning-player deal and an A/B arm are all the same mechanism, and the price a player was actually shown is a row that can be cited afterwards.';
COMMENT ON COLUMN "offer_prices"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "offer_prices"."offer_id" IS 'Offer being priced.';
COMMENT ON COLUMN "offer_prices"."audience_code" IS 'Who this price is for, matched against players.segment_code, a country or an experiment arm. The literal value default is the catch-all.';
COMMENT ON COLUMN "offer_prices"."price_minor" IS 'Price for this audience, in the smallest unit of the offer currency.';
COMMENT ON COLUMN "offer_prices"."priority" IS 'Tie-break when a player matches several audiences. Highest priority wins, so pricing is deterministic rather than dependent on row order.';
COMMENT ON COLUMN "offer_prices"."starts_at" IS 'Optional window for a temporary discount on one audience. Null means it applies for the whole offer window.';
COMMENT ON COLUMN "offer_prices"."ends_at" IS 'End of the optional window.';

CREATE UNIQUE INDEX "uq_offer_prices_offer_audience"
ON "offer_prices" ("offer_id", "audience_code");

CREATE TABLE IF NOT EXISTS "purchases" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Buyer.
	"player_id" BIGINT NOT NULL,
	-- Offer bought. Nullable so a retired offer can be deleted without destroying the purchase record.
	"offer_id" BIGINT,
	-- Price row that was applied. Kept so a pricing dispute can be settled by pointing at the exact rule that matched.
	"offer_price_id" BIGINT,
	-- Units of the offer bought in this transaction.
	"quantity" INTEGER NOT NULL DEFAULT 1,
	-- Price snapshot at purchase time. Never re-read from offer_prices, because the whole point of personalised pricing is that the rule may no longer apply.
	"price_minor" BIGINT NOT NULL,
	-- Currency the price was charged in, snapshotted alongside it.
	"currency_id" BIGINT NOT NULL,
	-- pending | completed | failed | refunded | charged_back. Only completed purchases delivered anything.
	"state" VARCHAR(20) NOT NULL DEFAULT 'pending',
	-- Transaction that debited the wallet and credited the sink. Null while pending or after a failure.
	"ledger_transaction_id" BIGINT,
	-- Transaction that undid it. A refund is a reversing journal entry plus this pointer, not a deletion and not a negative row bolted onto the original.
	"reversal_transaction_id" BIGINT,
	-- support | store_refund | chargeback | fraud. Chargebacks are separated because they carry a fee and usually a payment block.
	"refund_reason" VARCHAR(40),
	-- Client-supplied key. Unique so a double tap on the buy button charges once.
	"idempotency_key" VARCHAR(120) NOT NULL UNIQUE,
	-- When the buy was attempted.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When delivery and the ledger write both succeeded.
	"completed_at" TIMESTAMPTZ,
	-- When the reversal was recorded.
	"refunded_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "purchases" IS 'One attempt to buy something with in-game currency. There is no refunds table: a refund is a reversing ledger transaction plus state on this row, which keeps a single timeline of what happened rather than two that can disagree.';
COMMENT ON COLUMN "purchases"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "purchases"."player_id" IS 'Buyer.';
COMMENT ON COLUMN "purchases"."offer_id" IS 'Offer bought. Nullable so a retired offer can be deleted without destroying the purchase record.';
COMMENT ON COLUMN "purchases"."offer_price_id" IS 'Price row that was applied. Kept so a pricing dispute can be settled by pointing at the exact rule that matched.';
COMMENT ON COLUMN "purchases"."quantity" IS 'Units of the offer bought in this transaction.';
COMMENT ON COLUMN "purchases"."price_minor" IS 'Price snapshot at purchase time. Never re-read from offer_prices, because the whole point of personalised pricing is that the rule may no longer apply.';
COMMENT ON COLUMN "purchases"."currency_id" IS 'Currency the price was charged in, snapshotted alongside it.';
COMMENT ON COLUMN "purchases"."state" IS 'pending | completed | failed | refunded | charged_back. Only completed purchases delivered anything.';
COMMENT ON COLUMN "purchases"."ledger_transaction_id" IS 'Transaction that debited the wallet and credited the sink. Null while pending or after a failure.';
COMMENT ON COLUMN "purchases"."reversal_transaction_id" IS 'Transaction that undid it. A refund is a reversing journal entry plus this pointer, not a deletion and not a negative row bolted onto the original.';
COMMENT ON COLUMN "purchases"."refund_reason" IS 'support | store_refund | chargeback | fraud. Chargebacks are separated because they carry a fee and usually a payment block.';
COMMENT ON COLUMN "purchases"."idempotency_key" IS 'Client-supplied key. Unique so a double tap on the buy button charges once.';
COMMENT ON COLUMN "purchases"."created_at" IS 'When the buy was attempted.';
COMMENT ON COLUMN "purchases"."completed_at" IS 'When delivery and the ledger write both succeeded.';
COMMENT ON COLUMN "purchases"."refunded_at" IS 'When the reversal was recorded.';

CREATE INDEX "idx_purchases_player_time"
ON "purchases" ("player_id", "created_at");
CREATE INDEX "idx_purchases_offer_state"
ON "purchases" ("offer_id", "state");
CREATE INDEX "idx_purchases_state_time"
ON "purchases" ("state", "created_at");

CREATE TABLE IF NOT EXISTS "iap_receipts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account credited.
	"player_id" BIGINT NOT NULL,
	-- Store purchase that minted currency, when one was created. Null for a receipt that failed validation and so never became a purchase.
	"purchase_id" BIGINT,
	-- apple | google | steam | web. Each has different validation semantics and different refund windows.
	"store" VARCHAR(16) NOT NULL,
	-- Product identifier as configured in the store console. Mapped to an offer at validation time.
	"store_product_id" VARCHAR(120) NOT NULL,
	-- The store own transaction id. Unique across the table, which is the single constraint that stops one receipt being redeemed on several accounts.
	"store_transaction_id" VARCHAR(160) NOT NULL UNIQUE,
	-- Real money charged, in minor units of the fiat currency. Integers only, never float.
	"price_minor" BIGINT NOT NULL,
	-- ISO 4217 code for price_minor, taken from the store rather than assumed from the country.
	"currency_code" CHAR(3) NOT NULL,
	-- pending | valid | invalid | revoked. Currency is minted only on valid, and revoked is what a store refund notification turns it into.
	"validation_state" VARCHAR(16) NOT NULL DEFAULT 'pending',
	-- Why validation failed. Kept because a spike in one error type is usually an integration problem rather than fraud.
	"validation_error" VARCHAR(200),
	-- The receipt exactly as the store returned it. Kept verbatim so a disputed transaction can be re-validated years later against the same bytes.
	"raw_payload" JSONB,
	-- Purchase time reported by the store, which is the timestamp finance reconciles against.
	"purchased_at" TIMESTAMPTZ NOT NULL,
	-- When the server confirmed it with the store.
	"validated_at" TIMESTAMPTZ,
	-- When the store told us the money went back. This triggers the reversing ledger transaction on the linked purchase.
	"revoked_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "iap_receipts" IS 'Proof that real money changed hands, validated against the store rather than trusted from the client. This is the only table where currency enters the economy from outside, which is why the store transaction id is unique.';
COMMENT ON COLUMN "iap_receipts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "iap_receipts"."player_id" IS 'Account credited.';
COMMENT ON COLUMN "iap_receipts"."purchase_id" IS 'Store purchase that minted currency, when one was created. Null for a receipt that failed validation and so never became a purchase.';
COMMENT ON COLUMN "iap_receipts"."store" IS 'apple | google | steam | web. Each has different validation semantics and different refund windows.';
COMMENT ON COLUMN "iap_receipts"."store_product_id" IS 'Product identifier as configured in the store console. Mapped to an offer at validation time.';
COMMENT ON COLUMN "iap_receipts"."store_transaction_id" IS 'The store own transaction id. Unique across the table, which is the single constraint that stops one receipt being redeemed on several accounts.';
COMMENT ON COLUMN "iap_receipts"."price_minor" IS 'Real money charged, in minor units of the fiat currency. Integers only, never float.';
COMMENT ON COLUMN "iap_receipts"."currency_code" IS 'ISO 4217 code for price_minor, taken from the store rather than assumed from the country.';
COMMENT ON COLUMN "iap_receipts"."validation_state" IS 'pending | valid | invalid | revoked. Currency is minted only on valid, and revoked is what a store refund notification turns it into.';
COMMENT ON COLUMN "iap_receipts"."validation_error" IS 'Why validation failed. Kept because a spike in one error type is usually an integration problem rather than fraud.';
COMMENT ON COLUMN "iap_receipts"."raw_payload" IS 'The receipt exactly as the store returned it. Kept verbatim so a disputed transaction can be re-validated years later against the same bytes.';
COMMENT ON COLUMN "iap_receipts"."purchased_at" IS 'Purchase time reported by the store, which is the timestamp finance reconciles against.';
COMMENT ON COLUMN "iap_receipts"."validated_at" IS 'When the server confirmed it with the store.';
COMMENT ON COLUMN "iap_receipts"."revoked_at" IS 'When the store told us the money went back. This triggers the reversing ledger transaction on the linked purchase.';

CREATE INDEX "idx_receipts_player_time"
ON "iap_receipts" ("player_id", "purchased_at");
CREATE INDEX "idx_receipts_store_state"
ON "iap_receipts" ("store", "validation_state");

CREATE TABLE IF NOT EXISTS "battle_passes" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Stable key, e.g. season_12_pass.
	"code" VARCHAR(40) NOT NULL UNIQUE,
	-- Display name.
	"name" VARCHAR(120) NOT NULL,
	-- When progress starts counting.
	"starts_at" TIMESTAMPTZ NOT NULL,
	-- When the pass closes. Unclaimed tiers are forfeited at this point, which is why claims must be recorded rather than inferred.
	"ends_at" TIMESTAMPTZ NOT NULL,
	-- Offer that unlocks the premium track. Null for a pass with no paid track.
	"premium_offer_id" BIGINT,
	-- Number of tiers. Denormalised from the tier rows so the progress bar renders without counting them.
	"tier_count" SMALLINT NOT NULL,
	-- Default step between tiers, used to generate the tier rows. The authoritative threshold is still on each tier, since late tiers usually cost more.
	"xp_per_tier" INTEGER NOT NULL,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "battle_passes" IS 'A seasonal progression track sold as a product. It is modelled next to the shop rather than inside it because the pass is a container of rewards, while the offer that unlocks it is just another thing for sale.';
COMMENT ON COLUMN "battle_passes"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "battle_passes"."code" IS 'Stable key, e.g. season_12_pass.';
COMMENT ON COLUMN "battle_passes"."name" IS 'Display name.';
COMMENT ON COLUMN "battle_passes"."starts_at" IS 'When progress starts counting.';
COMMENT ON COLUMN "battle_passes"."ends_at" IS 'When the pass closes. Unclaimed tiers are forfeited at this point, which is why claims must be recorded rather than inferred.';
COMMENT ON COLUMN "battle_passes"."premium_offer_id" IS 'Offer that unlocks the premium track. Null for a pass with no paid track.';
COMMENT ON COLUMN "battle_passes"."tier_count" IS 'Number of tiers. Denormalised from the tier rows so the progress bar renders without counting them.';
COMMENT ON COLUMN "battle_passes"."xp_per_tier" IS 'Default step between tiers, used to generate the tier rows. The authoritative threshold is still on each tier, since late tiers usually cost more.';

CREATE TABLE IF NOT EXISTS "battle_pass_tiers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Pass the tier belongs to.
	"battle_pass_id" BIGINT NOT NULL,
	-- Position in the track, starting at one. Ordering is explicit because thresholds are not evenly spaced.
	"tier_index" SMALLINT NOT NULL,
	-- Cumulative experience to reach this tier. Cumulative rather than incremental so current tier is a single comparison against progress.
	"xp_required" INTEGER NOT NULL,
	-- currency | item | cosmetic | xp_boost for the free track. Null when a tier gives free players nothing.
	"free_reward_type" VARCHAR(32),
	-- Identifier of the free reward within its type. Null when there is no free reward.
	"free_reward_ref" VARCHAR(80),
	-- Amount granted on the free track.
	"free_reward_quantity" INTEGER,
	-- Reward type for the premium track. Null on the rare tier that is free-only.
	"premium_reward_type" VARCHAR(32),
	-- Identifier of the premium reward within its type.
	"premium_reward_ref" VARCHAR(80),
	-- Amount granted on the premium track.
	"premium_reward_quantity" INTEGER,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "battle_pass_tiers" IS 'One rung of the ladder, carrying both tracks side by side. Two reward columns rather than a rewards table is a deliberate simplification: a battle pass tier has exactly one free and one premium reward, and modelling it as a collection buys nothing.';
COMMENT ON COLUMN "battle_pass_tiers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "battle_pass_tiers"."battle_pass_id" IS 'Pass the tier belongs to.';
COMMENT ON COLUMN "battle_pass_tiers"."tier_index" IS 'Position in the track, starting at one. Ordering is explicit because thresholds are not evenly spaced.';
COMMENT ON COLUMN "battle_pass_tiers"."xp_required" IS 'Cumulative experience to reach this tier. Cumulative rather than incremental so current tier is a single comparison against progress.';
COMMENT ON COLUMN "battle_pass_tiers"."free_reward_type" IS 'currency | item | cosmetic | xp_boost for the free track. Null when a tier gives free players nothing.';
COMMENT ON COLUMN "battle_pass_tiers"."free_reward_ref" IS 'Identifier of the free reward within its type. Null when there is no free reward.';
COMMENT ON COLUMN "battle_pass_tiers"."free_reward_quantity" IS 'Amount granted on the free track.';
COMMENT ON COLUMN "battle_pass_tiers"."premium_reward_type" IS 'Reward type for the premium track. Null on the rare tier that is free-only.';
COMMENT ON COLUMN "battle_pass_tiers"."premium_reward_ref" IS 'Identifier of the premium reward within its type.';
COMMENT ON COLUMN "battle_pass_tiers"."premium_reward_quantity" IS 'Amount granted on the premium track.';

CREATE UNIQUE INDEX "uq_tiers_pass_index"
ON "battle_pass_tiers" ("battle_pass_id", "tier_index");

CREATE TABLE IF NOT EXISTS "battle_pass_progress" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Player on the track.
	"player_id" BIGINT NOT NULL,
	-- Pass being progressed.
	"battle_pass_id" BIGINT NOT NULL,
	-- Cumulative experience this season. Current tier is derived from it, not stored twice.
	"xp" INTEGER NOT NULL DEFAULT 0,
	-- Whether the paid track is unlocked. Set by a completed purchase and never revoked except by a chargeback.
	"has_premium" BOOLEAN NOT NULL DEFAULT false,
	-- Purchase that unlocked the premium track. Null on the free track, and the link a chargeback follows to lock it again.
	"premium_purchase_id" BIGINT,
	-- First experience gain, which is when the row is created.
	"started_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Last experience gain.
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "battle_pass_progress" IS 'A player position on one pass. Buying premium halfway through retroactively entitles every tier already earned, which works only because entitlement is derived from xp and claims are recorded separately.';
COMMENT ON COLUMN "battle_pass_progress"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "battle_pass_progress"."player_id" IS 'Player on the track.';
COMMENT ON COLUMN "battle_pass_progress"."battle_pass_id" IS 'Pass being progressed.';
COMMENT ON COLUMN "battle_pass_progress"."xp" IS 'Cumulative experience this season. Current tier is derived from it, not stored twice.';
COMMENT ON COLUMN "battle_pass_progress"."has_premium" IS 'Whether the paid track is unlocked. Set by a completed purchase and never revoked except by a chargeback.';
COMMENT ON COLUMN "battle_pass_progress"."premium_purchase_id" IS 'Purchase that unlocked the premium track. Null on the free track, and the link a chargeback follows to lock it again.';
COMMENT ON COLUMN "battle_pass_progress"."started_at" IS 'First experience gain, which is when the row is created.';
COMMENT ON COLUMN "battle_pass_progress"."updated_at" IS 'Last experience gain.';

CREATE UNIQUE INDEX "uq_progress_player_pass"
ON "battle_pass_progress" ("player_id", "battle_pass_id");

CREATE TABLE IF NOT EXISTS "battle_pass_claims" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Player progress row the claim belongs to.
	"progress_id" BIGINT NOT NULL,
	-- Tier being collected.
	"tier_id" BIGINT NOT NULL,
	-- free | premium. The same tier can be claimed once on each track, which is exactly what buying premium late has to allow.
	"track" VARCHAR(8) NOT NULL,
	-- Transaction that credited a currency reward. Null for item or cosmetic rewards, which are fulfilled by the inventory service.
	"ledger_transaction_id" BIGINT,
	-- Collection time. Claims are recorded rather than inferred from xp because rewards are collected manually and expire when the pass ends.
	"claimed_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "battle_pass_claims" IS 'Proof that a reward was handed over. The unique key is the whole anti-double-claim mechanism, and it is what lets the premium track be unlocked late without either duplicating or skipping anything.';
COMMENT ON COLUMN "battle_pass_claims"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "battle_pass_claims"."progress_id" IS 'Player progress row the claim belongs to.';
COMMENT ON COLUMN "battle_pass_claims"."tier_id" IS 'Tier being collected.';
COMMENT ON COLUMN "battle_pass_claims"."track" IS 'free | premium. The same tier can be claimed once on each track, which is exactly what buying premium late has to allow.';
COMMENT ON COLUMN "battle_pass_claims"."ledger_transaction_id" IS 'Transaction that credited a currency reward. Null for item or cosmetic rewards, which are fulfilled by the inventory service.';
COMMENT ON COLUMN "battle_pass_claims"."claimed_at" IS 'Collection time. Claims are recorded rather than inferred from xp because rewards are collected manually and expire when the pass ends.';

CREATE UNIQUE INDEX "uq_claims_progress_tier_track"
ON "battle_pass_claims" ("progress_id", "tier_id", "track");

